<?php $base='../';require_once '../config/config.php';require_admin();if($_SERVER['REQUEST_METHOD']==='POST'){check_csrf();$img=null;if(!empty($_FILES['image']['name'])){$ext=strtolower(pathinfo($_FILES['image']['name'],PATHINFO_EXTENSION));if(in_array($ext,['jpg','jpeg','png','webp'])){$img=uniqid('project_',true).'.'.$ext;move_uploaded_file($_FILES['image']['tmp_name'],'../uploads/'.$img);}}db()->prepare('INSERT INTO projects(title,description,category,image,video_url) VALUES(?,?,?,?,?)')->execute([$_POST['title'],$_POST['description'],$_POST['category'],$img,$_POST['video_url']]);header('Location: projects.php');exit;}$rows=db()->query('SELECT * FROM projects ORDER BY project_id DESC')->fetchAll();$title='Portfolio Management';include '../includes/header.php';?><section class="section"><div class="container"><h1>Portfolio Projects</h1><form method="post" enctype="multipart/form-data" class="card p-4 my-4"><input type="hidden" name="csrf" value="<?=csrf()?>"><div class="row g-2"><div class="col-md-4"><input class="form-control" name="title" placeholder="Project title" required></div><div class="col-md-3"><input class="form-control" name="category" placeholder="Category" required></div><div class="col-md-5"><input class="form-control" name="video_url" placeholder="Video URL"></div><div class="col-12"><textarea class="form-control" name="description" placeholder="Description"></textarea></div><div class="col-md-8"><input class="form-control" type="file" name="image"></div><div class="col-md-4"><button class="btn btn-gold w-100">Add Project</button></div></div></form><div class="row g-4"><?php foreach($rows as $r):?><div class="col-md-4"><div class="card p-3"><h4><?=e($r['title'])?></h4><span class="gold"><?=e($r['category'])?></span><p><?=e($r['description'])?></p></div></div><?php endforeach;?></div></div></section><?php include '../includes/footer.php';?>
